const title = items[0].json.title;
const company = title.replace('Due Diligence:', '').trim();
const description = items[0].json.description || '';

// Extract website from description
const websiteMatch = description.match(/(https?:\/\/[^\s]+)/);
const website = websiteMatch ? websiteMatch[0] : '';

// Check if task has PDF attachments
const hasAttachments = items[0].json.attachment_count > 0;

return [{
  json: {
    taskId: items[0].json.id,
    title: items[0].json.title,
    company,
    website,
    description,
    hasAttachments,
    originalData: items[0].json
  }
}];

// Categorize content as financial or non-financial
const financialKeywords = ['financial', 'revenue', 'profit', 'loss', 'balance sheet', 'income statement', 'cash flow', 'audit', 'tax', 'accounting'];

const content = $json.text || $json.content || '';
const fileName = $json.name || '';

let isFinancial = false;

// Check if content contains financial keywords
for (const keyword of financialKeywords) {
  if (content.toLowerCase().includes(keyword) || fileName.toLowerCase().includes(keyword)) {
    isFinancial = true;
    break;
  }
}

return {
  category: isFinancial ? 'financial' : 'non-financial',
  content: content,
  source: fileName ? 'pdf' : 'website',
  fileName: fileName || 'website',
  ...$json
};

// Store content in knowledge base (simplified version)
const staticData = $workflow.getStaticData('global');
let knowledgeBase = staticData.knowledgeBase || {};

if (!knowledgeBase[$json.taskId]) {
  knowledgeBase[$json.taskId] = {
    financial: [],
    nonFinancial: [],
    website: null
  };
}

if ($json.category === 'financial') {
  knowledgeBase[$json.taskId].financial.push({
    content: $json.content,
    source: $json.source,
    fileName: $json.fileName
  });
} else if ($json.source === 'website') {
  knowledgeBase[$json.taskId].website = $json.content;
} else {
  knowledgeBase[$json.taskId].nonFinancial.push({
    content: $json.content,
    source: $json.source,
    fileName: $json.fileName
  });
}

staticData.knowledgeBase = knowledgeBase;

return items;

// Check if section already completed
const staticData = $workflow.getStaticData('global');
let completedSections = staticData.completedSections || {};
const taskId = $json.taskId;
const section = $json.section;

if (!completedSections[taskId]) {
  completedSections[taskId] = {};
}

// Skip if section already completed
if (completedSections[taskId][section]) {
  return null; // Skip this item
}

return items;

