// Store approved section in knowledge base
const staticData = $workflow.getStaticData('global');
let completedSections = staticData.completedSections || {};
const taskId = $json.taskId;
const section = $json.section;

if (!completedSections[taskId]) {
  completedSections[taskId] = {};
}

completedSections[taskId][section] = {
  content: $('Maker AI - Generate Section').first().json.response,
  timestamp: new Date().toISOString(),
  status: 'approved'
};

staticData.completedSections = completedSections;

// Define all 20 DD sections
const allSections = [
  'Introduction & Engagement Context',
  'Methodology & Reliability Levels',
  'Company Overview',
  'Business Model & Unit Economics',
  'Products & Technology',
  'Target Market & Competitive Set',
  'Financials (Multi-Year, reconciled & recomputed)',
  'Cash, Burn, Runway',
  'Revenue Quality & Client Cohorts',
  'Partnerships & Ecosystem',
  'Intellectual Property',
  'Legal & Regulatory',
  'Governance & Board Effectiveness',
  'Capital Structure & Dilution',
  'Risk Matrix & Mitigations',
  'Gaps, Uncertainties & Disclaimers',
  'Scenario Analysis',
  'Strategic Options',
  'Recommendations & Next Steps',
  'Source Map & Integrity Log'
];

const completedCount = Object.keys(completedSections[taskId] || {}).length;

return [{
  json: {
    ...$json,
    allSectionsCompleted: completedCount >= allSections.length,
    completedCount,
    totalSections: allSections.length
  }
}];

// Generate final PDF report
const staticData = $workflow.getStaticData('global');
const completedSections = staticData.completedSections || {};
const taskId = $json.taskId;
const sections = completedSections[taskId] || {};

// Create report content
let reportContent = `DUE DILIGENCE REPORT: ${$json.company}\n\n`;
reportContent += `Generated on: ${new Date().toISOString()}\n\n`;

// Add all sections in order
for (const [sectionName, sectionData] of Object.entries(sections)) {
  reportContent += `=== ${sectionName.toUpperCase()} ===\n\n`;
  reportContent += `${sectionData.content}\n\n`;
}

return [{
  json: {
    ...$json,
    reportContent
  }
}];

